The bug: the key shape in demo 1 (cells (9,5),(10,4),(10,6)) is not 4-connected, so my component extraction collapsed it to a single cell. Using 8-connectivity (or just the key cells themselves) fixes the shape. I re-verified: demo 1 has exactly 8 fit positions for the caret shape, and demo 2's stamp matches the key shape exactly.

```python
from collections import deque, Counter

def transform(grid):
    H = len(grid); W = len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    keycells = [(r, c) for r in range(H) for c in range(W)
                if grid[r][c] != bg and grid[r][c] != 0]
    g = [row[:] for row in grid]
    if not keycells:
        return g
    key = grid[keycells[0][0]][keycells[0][1]]
    ks = set(keycells)
    # largest 8-connected component among key cells
    seen = set()
    best = set()
    for p in keycells:
        if p in seen:
            continue
        comp = {p}
        dq = deque([p])
        seen.add(p)
        while dq:
            r, c = dq.popleft()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    q = (r + dr, c + dc)
                    if q in ks and q not in seen:
                        seen.add(q); comp.add(q); dq.append(q)
        if len(comp) > len(best):
            best = comp
    comp = best
    mr = min(r for r, c in comp); mc = min(c for r, c in comp)
    offs = sorted((r - mr, c - mc) for r, c in comp)
    for r in range(H):
        for c in range(W):
            if all(0 <= r + dr < H and 0 <= c + dc < W and grid[r + dr][c + dc] == 0
                   for dr, dc in offs):
                for dr, dc in offs:
                    g[r + dr][c + dc] = key
    return g
