Fix: identify the key color directly as the least common non-zero color (1 in the test, 6/5 in the demos), and don't rely on background detection at all — stamps go wherever all shape cells are 0 in the input.

```python
from collections import Counter

def transform(grid):
    H = len(grid); W = len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    nonzero = [(cnt[v], v) for v in cnt if v != 0]
    if not nonzero:
        return [row[:] for row in grid]
    key = min(nonzero)[1]
    keycells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == key]
    if not keycells:
        return [row[:] for row in grid]
    mr = min(r for r, c in keycells); mc = min(c for r, c in keycells)
    offs = sorted((r - mr, c - mc) for r, c in keycells)
    g = [row[:] for row in grid]
    for r in range(H):
        for c in range(W):
            if all(0 <= r + dr < H and 0 <= c + dc < W and grid[r + dr][c + dc] == 0
                   for dr, dc in offs):
                for dr, dc in offs:
                    g[r + dr][c + dc] = key
    return g
